# Job 42: fix Abby's hunched back / dropped shoulders in walk / jog / run.
# RTG_AutoGenerated's target "Default Pose" auto-aligned Abby's torso to Mixamo's straight T-pose spine:
#   pelvis -6.8, spine_01 -14.7, spine_02 +7.3, spine_03 +9.5, spine_04 +8.5 (degrees).
# Every retargeted frame inherits that, so the upper back rounds ~25 deg more than in the source.
# Copy the retargeter, build retarget poses without those torso offsets (arms keep their A->T alignment),
# batch-retarget the Mixamo clips with each variant and measure them against the source (job 41 metrics).
import math
import unreal

EAL = unreal.EditorAssetLibrary
DIR = "/Game/Abby_Animation/Posture"
RTG = DIR + "/RTG_Mixamo_To_Abby_Posture"
T = unreal.RetargetSourceOrTarget.TARGET
SOURCES = ["/Game/Animation2/Walking_Anim", "/Game/Animation2/Jogging", "/Game/Animation2/Running__2_"]
VARIANTS = {
    # A: no torso offsets at all
    "A": {"pelvis": 0.0, "spine_01": 0.0, "spine_02": 0.0, "spine_03": 0.0, "spine_04": 0.0},
    # B: keep the pelvis offset (legs unchanged), cancel it at spine_01, natural curve above
    "B": {"pelvis": -6.8, "spine_01": 6.8, "spine_02": 0.0, "spine_03": 0.0, "spine_04": 0.0},
}

if not EAL.does_directory_exist(DIR):
    EAL.make_directory(DIR)
if not EAL.does_asset_exist(RTG):
    EAL.duplicate_asset("/Game/Abby_Animation/RetargetAssets/RTG_AutoGenerated", RTG)
rtg = unreal.load_asset(RTG)
c = unreal.IKRetargeterController.get_controller(rtg)

for key, offsets in VARIANTS.items():
    pose = "UprightSpine_" + key
    if pose not in [str(p) for p in c.get_retarget_poses(T)]:
        c.duplicate_retarget_pose("Default Pose", pose, T)
    c.set_current_retarget_pose(pose, T)
    for bone, yaw in offsets.items():
        c.set_rotation_offset_for_retarget_pose_bone(bone, unreal.Rotator(roll=0.0, pitch=0.0, yaw=yaw).quaternion(), T)
    print(pose, {b: round(c.get_rotation_offset_for_retarget_pose_bone(b, T).rotator().yaw, 1) for b in offsets},
          "upperarm_l pitch", round(c.get_rotation_offset_for_retarget_pose_bone("upperarm_l", T).rotator().pitch, 1))
    EAL.save_loaded_asset(rtg, only_if_is_dirty=False)

    inputs = unreal.IKRetargetBatchOperationInputs()
    inputs.assets_to_retarget = [EAL.find_asset_data(p) for p in SOURCES]
    inputs.source_mesh = unreal.load_asset("/Game/Animation2/Walking")
    inputs.target_mesh = unreal.load_asset("/Game/MetaHumans/MH_CH_Abby5/Body/SKM_MH_CH_Abby5_BodyMesh")
    inputs.ik_retarget_asset = rtg
    inputs.target_path = DIR
    inputs.use_source_path = False
    inputs.prefix = "Abby_"
    inputs.suffix = "_" + key
    inputs.include_referenced_assets = False
    inputs.overwrite_existing_files = True
    for a in unreal.IKRetargetBatchOperation.run_batch_retarget(inputs):
        EAL.save_asset(str(a.package_name), only_if_is_dirty=False)
        print("  ->", a.package_name)
